INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000870', 'Surfaktan adalah zat yang dapat...', 'A surfactant is a substance that can...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:51:"Menurunkan tegangan antarmuka antara minyak dan air";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:26:"Menaikkan porositas batuan";i:3;s:28:"Menurunkan tekanan reservoir";}', 'a:4:{i:0;s:48:"Reduce interfacial tension between oil and water";i:1;s:22:"Increase oil viscosity";i:2;s:22:"Increase rock porosity";i:3;s:24:"Lower reservoir pressure";}', '', 'Menurunkan tegangan antarmuka antara minyak dan air', 'Reduce interfacial tension between oil and water', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000871', 'Molekul surfaktan memiliki bagian...', 'A surfactant molecule has a part that is...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:49:"Hidrofilik (suka air) dan lipofilik (suka minyak)";i:1;s:16:"Hanya hidrofilik";i:2;s:15:"Hanya lipofilik";i:3;s:12:"Bersifat gas";}', 'a:4:{i:0;s:54:"Hydrophilic (water-loving) and lipophilic (oil-loving)";i:1;s:16:"Only hydrophilic";i:2;s:15:"Only lipophilic";i:3;s:7:"Gaseous";}', '', 'Hidrofilik (suka air) dan lipofilik (suka minyak)', 'Hydrophilic (water-loving) and lipophilic (oil-loving)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000872', 'Contoh surfaktan anionik yang umum dipakai pada EOR adalah...', 'An example of an anionic surfactant commonly used in EOR is...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:8:"Sulfonat";i:1;s:4:"NaCl";i:2;s:3:"CO2";i:3;s:6:"Metana";}', 'a:4:{i:0;s:9:"Sulfonate";i:1;s:4:"NaCl";i:2;s:3:"CO2";i:3;s:7:"Methane";}', '', 'Sulfonat', 'Sulfonate', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000873', 'Alkali yang sering digunakan pada alkaline flooding adalah...', 'Alkalis often used in alkaline flooding are...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:15:"NaOH dan Na2CO3";i:1;s:13:"HCl dan H2SO4";i:2;s:10:"CO2 dan N2";i:3;s:12:"CH4 dan C2H6";}', 'a:4:{i:0;s:15:"NaOH and Na2CO3";i:1;s:13:"HCl and H2SO4";i:2;s:10:"CO2 and N2";i:3;s:12:"CH4 and C2H6";}', '', 'NaOH dan Na2CO3', 'NaOH and Na2CO3', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000874', 'Alkaline flooding bekerja melalui pembentukan...', 'Alkaline flooding works through the formation of...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:50:"Surfaktan in-situ dari reaksi dengan asam naftenat";i:1;s:10:"Gas metana";i:2;s:12:"Mineral baru";i:3;s:5:"Semen";}', 'a:4:{i:0;s:55:"In-situ surfactants from reaction with naphthenic acids";i:1;s:11:"Methane gas";i:2;s:12:"New minerals";i:3;s:6:"Cement";}', '', 'Surfaktan in-situ dari reaksi dengan asam naftenat', 'In-situ surfactants from reaction with naphthenic acids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000875', 'ASP flooding merupakan kombinasi dari...', 'ASP flooding is a combination of...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:32:"Alkaline, Surfaktan, dan Polimer";i:1;s:23:"Air, Steam, dan Polimer";i:2;s:25:"Asam, Sulfur, dan Propana";i:3;s:28:"Alkaline, Steam, dan Propana";}', 'a:4:{i:0;s:33:"Alkaline, Surfactant, and Polymer";i:1;s:23:"Air, Steam, and Polymer";i:2;s:25:"Acid, Sulfur, and Propane";i:3;s:28:"Alkaline, Steam, and Propane";}', '', 'Alkaline, Surfaktan, dan Polimer', 'Alkaline, Surfactant, and Polymer', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000876', 'Mikroemulsi pada surfaktan flooding terbentuk ketika...', 'A microemulsion in surfactant flooding forms when...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:57:"Minyak, air, dan surfaktan membentuk fasa campuran stabil";i:1;s:21:"Air dan gas bercampur";i:2;s:22:"Batuan larut dalam air";i:3;s:20:"Polimer terdegradasi";}', 'a:4:{i:0;s:52:"Oil, water, and surfactant form a stable mixed phase";i:1;s:17:"Water and gas mix";i:2;s:23:"Rock dissolves in water";i:3;s:16:"Polymer degrades";}', '', 'Minyak, air, dan surfaktan membentuk fasa campuran stabil', 'Oil, water, and surfactant form a stable mixed phase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000877', 'Manakah jenis surfaktan yang umum digunakan pada EOR?', 'Which surfactant types are commonly used in EOR?', 'multi', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:7:"Anionik";i:1;s:8:"Nonionik";i:2;s:8:"Kationik";i:3;s:11:"Logam berat";}', 'a:4:{i:0;s:7:"Anionic";i:1;s:8:"Nonionic";i:2;s:8:"Cationic";i:3;s:11:"Heavy metal";}', '', 'a:3:{i:0;s:7:"Anionik";i:1;s:8:"Nonionik";i:2;s:8:"Kationik";}', 'a:3:{i:0;s:7:"Anionic";i:1;s:8:"Nonionic";i:2;s:8:"Cationic";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000878', 'Urutkan urutan injeksi pada proses ASP flooding.', 'Arrange the injection sequence in the ASP flooding process.', 'drag', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:8:"Preflush";i:1;s:23:"Slug alkaline-surfaktan";i:2;s:12:"Slug polimer";i:3;s:11:"Chase water";}', 'a:4:{i:0;s:8:"Preflush";i:1;s:24:"Alkaline-surfactant slug";i:2;s:12:"Polymer slug";i:3;s:11:"Chase water";}', '', 'a:4:{i:0;s:8:"Preflush";i:1;s:23:"Slug alkaline-surfaktan";i:2;s:12:"Slug polimer";i:3;s:11:"Chase water";}', 'a:4:{i:0;s:8:"Preflush";i:1;s:24:"Alkaline-surfactant slug";i:2;s:12:"Polymer slug";i:3;s:11:"Chase water";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000879', 'Benarkah surfaktan dapat menurunkan tegangan antarmuka hingga beberapa orde besaran?', 'Is it true that surfactants can reduce interfacial tension by several orders of magnitude?', 'yesorno', 'PFC000000010', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000880', 'Penurunan IFT dari 30 mN/m menjadi 0,003 mN/m akan menaikkan bilangan kapiler sekitar...', 'Reducing IFT from 30 mN/m to 0.003 mN/m will increase the capillary number by about...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:11:"10.000 kali";i:1;s:8:"100 kali";i:2;s:7:"10 kali";i:3;s:13:"Tidak berubah";}', 'a:4:{i:0;s:12:"10,000 times";i:1;s:9:"100 times";i:2;s:8:"10 times";i:3;s:9:"No change";}', '', '10.000 kali', '10,000 times', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000881', 'Pada klasifikasi Winsor, tipe III menggambarkan sistem...', 'In the Winsor classification, type III describes a system...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:38:"Tiga fasa dengan mikroemulsi di tengah";i:1;s:9:"Satu fasa";i:2;s:30:"Dua fasa dengan minyak di atas";i:3;s:27:"Dua fasa dengan air di atas";}', 'a:4:{i:0;s:47:"Three phases with a microemulsion in the middle";i:1;s:9:"One phase";i:2;s:26:"Two phases with oil on top";i:3;s:28:"Two phases with water on top";}', '', 'Tiga fasa dengan mikroemulsi di tengah', 'Three phases with a microemulsion in the middle', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000882', 'Optimum salinity pada surfaktan flooding adalah kondisi di mana...', 'Optimum salinity in surfactant flooding is the condition where...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:57:"Tegangan antarmuka mencapai minimum dan recovery maksimum";i:1;s:22:"Surfaktan terdegradasi";i:2;s:17:"Polimer mengendap";i:3;s:21:"Tidak ada mikroemulsi";}', 'a:4:{i:0;s:61:"Interfacial tension reaches a minimum and recovery is maximum";i:1;s:19:"Surfactant degrades";i:2;s:20:"Polymer precipitates";i:3;s:22:"No microemulsion forms";}', '', 'Tegangan antarmuka mencapai minimum dan recovery maksimum', 'Interfacial tension reaches a minimum and recovery is maximum', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000883', 'Nilai HLB (hydrophile-lipophile balance) yang tinggi menunjukkan surfaktan lebih...', 'A high HLB (hydrophile-lipophile balance) value indicates the surfactant is more...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:22:"Hidrofilik (larut air)";i:1;s:24:"Lipofilik (larut minyak)";i:2;s:12:"Bersifat gas";i:3;s:23:"Tidak larut sama sekali";}', 'a:4:{i:0;s:27:"Hydrophilic (water-soluble)";i:1;s:24:"Lipophilic (oil-soluble)";i:2;s:7:"Gaseous";i:3;s:20:"Completely insoluble";}', '', 'Hidrofilik (larut air)', 'Hydrophilic (water-soluble)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000884', 'Konsumsi alkali di reservoir terutama disebabkan oleh...', 'Alkali consumption in the reservoir is mainly caused by...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:44:"Reaksi dengan mineral batuan dan ion divalen";i:1;s:18:"Penguapan ke udara";i:2;s:15:"Pembentukan gas";i:3;s:32:"Pencampuran dengan minyak ringan";}', 'a:4:{i:0;s:46:"Reactions with rock minerals and divalent ions";i:1;s:22:"Evaporation to the air";i:2;s:13:"Gas formation";i:3;s:21:"Mixing with light oil";}', '', 'Reaksi dengan mineral batuan dan ion divalen', 'Reactions with rock minerals and divalent ions', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000885', 'Risiko utama injeksi alkali pada batupasir adalah...', 'The main risk of alkali injection in sandstone is...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Pembentukan scale dan kerusakan formasi";i:1;s:21:"Peningkatan porositas";i:2;s:24:"Penurunan viskositas air";i:3;s:25:"Peningkatan permeabilitas";}', 'a:4:{i:0;s:36:"Scale formation and formation damage";i:1;s:18:"Increased porosity";i:2;s:23:"Reduced water viscosity";i:3;s:22:"Increased permeability";}', '', 'Pembentukan scale dan kerusakan formasi', 'Scale formation and formation damage', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000886', 'Surfaktan flooding umumnya paling efektif bila diikuti oleh...', 'Surfactant flooding is generally most effective when followed by...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:42:"Slug polimer untuk mengendalikan mobilitas";i:1;s:15:"Injeksi gas CO2";i:2;s:22:"Air tawar tanpa aditif";i:3;s:5:"Semen";}', 'a:4:{i:0;s:35:"A polymer slug for mobility control";i:1;s:17:"CO2 gas injection";i:2;s:29:"Fresh water without additives";i:3;s:6:"Cement";}', '', 'Slug polimer untuk mengendalikan mobilitas', 'A polymer slug for mobility control', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000887', 'Surfaktan anionik umumnya kurang cocok pada air formasi dengan...', 'Anionic surfactants are generally less suitable in formation water with...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:34:"Kadar kalsium dan magnesium tinggi";i:1;s:16:"Salinitas rendah";i:2;s:11:"Suhu rendah";i:3;s:9:"pH netral";}', 'a:4:{i:0;s:34:"High calcium and magnesium content";i:1;s:12:"Low salinity";i:2;s:15:"Low temperature";i:3;s:10:"Neutral pH";}', '', 'Kadar kalsium dan magnesium tinggi', 'High calcium and magnesium content', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000888', 'Adsorpsi surfaktan pada batuan menyebabkan...', 'Surfactant adsorption on rock causes...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:57:"Kehilangan surfaktan sehingga slug menjadi kurang efektif";i:1;s:33:"Peningkatan konsentrasi surfaktan";i:2;s:15:"Peningkatan IFT";i:3;s:21:"Peningkatan porositas";}', 'a:4:{i:0;s:50:"Surfactant loss so the slug becomes less effective";i:1;s:34:"Increased surfactant concentration";i:2;s:13:"Increased IFT";i:3;s:18:"Increased porosity";}', '', 'Kehilangan surfaktan sehingga slug menjadi kurang efektif', 'Surfactant loss so the slug becomes less effective', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000889', 'Pada alkaline flooding, penurunan IFT terjadi karena...', 'In alkaline flooding, IFT reduction occurs because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:51:"Terbentuk surfaktan alami (soap) dari asam naftenat";i:1;s:17:"Terbentuk gas CO2";i:2;s:31:"Alkali menaikkan viskositas air";i:3;s:24:"Alkali melarutkan kuarsa";}', 'a:4:{i:0;s:53:"Natural surfactants (soap) form from naphthenic acids";i:1;s:13:"CO2 gas forms";i:2;s:32:"Alkali increases water viscosity";i:3;s:23:"Alkali dissolves quartz";}', '', 'Terbentuk surfaktan alami (soap) dari asam naftenat', 'Natural surfactants (soap) form from naphthenic acids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000890', 'Kombinasi alkali dan surfaktan bersifat sinergis karena...', 'The combination of alkali and surfactant is synergistic because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:67:"Alkali menurunkan adsorpsi surfaktan dan menambah surfaktan in-situ";i:1;s:20:"Alkali menaikkan IFT";i:2;s:36:"Alkali menurunkan viskositas polimer";i:3;s:27:"Alkali menghilangkan minyak";}', 'a:4:{i:0;s:64:"Alkali reduces surfactant adsorption and adds in-situ surfactant";i:1;s:20:"Alkali increases IFT";i:2;s:32:"Alkali reduces polymer viscosity";i:3;s:22:"Alkali removes the oil";}', '', 'Alkali menurunkan adsorpsi surfaktan dan menambah surfaktan in-situ', 'Alkali reduces surfactant adsorption and adds in-situ surfactant', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000891', 'Surfaktan flooding pada reservoir karbonat umumnya lebih menantang karena...', 'Surfactant flooding in carbonate reservoirs is generally more challenging because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:77:"Permukaan batuan cenderung positif sehingga adsorpsi surfaktan anionik tinggi";i:1;s:24:"Porositas terlalu tinggi";i:2;s:16:"Tidak ada minyak";i:3;s:18:"Suhu selalu rendah";}', 'a:4:{i:0;s:74:"Rock surfaces tend to be positive so anionic surfactant adsorption is high";i:1;s:20:"Porosity is too high";i:2;s:15:"There is no oil";i:3;s:25:"Temperature is always low";}', '', 'Permukaan batuan cenderung positif sehingga adsorpsi surfaktan anionik tinggi', 'Rock surfaces tend to be positive so anionic surfactant adsorption is high', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000892', 'Manakah mekanisme yang berperan pada alkaline flooding?', 'Which mechanisms play a role in alkaline flooding?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Penurunan IFT melalui surfaktan in-situ";i:1;s:21:"Perubahan wettability";i:2;s:12:"Emulsifikasi";i:3;s:29:"Peningkatan viskositas minyak";}', 'a:4:{i:0;s:41:"IFT reduction through in-situ surfactants";i:1;s:22:"Wettability alteration";i:2;s:14:"Emulsification";i:3;s:24:"Increasing oil viscosity";}', '', 'a:3:{i:0;s:39:"Penurunan IFT melalui surfaktan in-situ";i:1;s:21:"Perubahan wettability";i:2;s:12:"Emulsifikasi";}', 'a:3:{i:0;s:41:"IFT reduction through in-situ surfactants";i:1;s:22:"Wettability alteration";i:2;s:14:"Emulsification";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000893', 'Manakah faktor yang memengaruhi desain slug surfaktan?', 'Which factors affect surfactant slug design?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:26:"Salinitas dan hardness air";i:1;s:14:"Suhu reservoir";i:2;s:31:"Jenis dan konsentrasi surfaktan";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:27:"Water salinity and hardness";i:1;s:21:"Reservoir temperature";i:2;s:33:"Surfactant type and concentration";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:26:"Salinitas dan hardness air";i:1;s:14:"Suhu reservoir";i:2;s:31:"Jenis dan konsentrasi surfaktan";}', 'a:3:{i:0;s:27:"Water salinity and hardness";i:1;s:21:"Reservoir temperature";i:2;s:33:"Surfactant type and concentration";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000894', 'Manakah fungsi polimer dalam proses ASP?', 'Which are the functions of polymer in the ASP process?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Mengendalikan mobilitas fluida pendesak";i:1;s:28:"Meningkatkan efisiensi sweep";i:2;s:20:"Mengurangi fingering";i:3;s:30:"Menurunkan IFT secara langsung";}', 'a:4:{i:0;s:44:"Control the mobility of the displacing fluid";i:1;s:24:"Improve sweep efficiency";i:2;s:16:"Reduce fingering";i:3;s:19:"Directly reduce IFT";}', '', 'a:3:{i:0;s:39:"Mengendalikan mobilitas fluida pendesak";i:1;s:28:"Meningkatkan efisiensi sweep";i:2;s:20:"Mengurangi fingering";}', 'a:3:{i:0;s:44:"Control the mobility of the displacing fluid";i:1;s:24:"Improve sweep efficiency";i:2;s:16:"Reduce fingering";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000895', 'Manakah keterbatasan alkaline flooding?', 'Which are limitations of alkaline flooding?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:42:"Konsumsi alkali tinggi pada batuan reaktif";i:1;s:12:"Risiko scale";i:2;s:45:"Tidak efektif pada minyak tanpa asam naftenat";i:3;s:30:"Selalu menaikkan permeabilitas";}', 'a:4:{i:0;s:41:"High alkali consumption in reactive rocks";i:1;s:10:"Scale risk";i:2;s:45:"Ineffective for oils without naphthenic acids";i:3;s:29:"Always increases permeability";}', '', 'a:3:{i:0;s:42:"Konsumsi alkali tinggi pada batuan reaktif";i:1;s:12:"Risiko scale";i:2;s:45:"Tidak efektif pada minyak tanpa asam naftenat";}', 'a:3:{i:0;s:41:"High alkali consumption in reactive rocks";i:1;s:10:"Scale risk";i:2;s:45:"Ineffective for oils without naphthenic acids";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
